import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../core/auth/auth_controller.dart';import '../features/onboarding/onboarding_screen.dart';import '../features/today/today_screen.dart';import '../features/profile/profile_screen.dart';
final routerProvider=Provider<GoRouter>((ref){final state=ref.watch(authControllerProvider);return GoRouter(initialLocation:'/welcome',redirect:(c,s){final protected=s.matchedLocation=='/today'||s.matchedLocation=='/profile';if(state==SessionState.authenticated&&(s.matchedLocation=='/welcome'||s.matchedLocation=='/onboarding'))return '/today';if(protected&&state==SessionState.anonymous)return '/welcome';if(protected&&state==SessionState.onboarding)return '/onboarding';return null;},routes:[GoRoute(path:'/welcome',builder:(_,__)=>const WelcomeScreen()),GoRoute(path:'/onboarding',builder:(_,__)=>const OnboardingScreen()),GoRoute(path:'/today',builder:(_,__)=>const TodayScreen()),GoRoute(path:'/profile',builder:(_,__)=>const ProfileScreen())]);});
class WelcomeScreen extends ConsumerWidget{const WelcomeScreen({super.key});@override Widget build(BuildContext c,WidgetRef r)=>Scaffold(body:SafeArea(child:Padding(padding:const EdgeInsets.all(28),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Spacer(),Text('ВЫХОД',style:Theme.of(c).textTheme.displayLarge),const Text('Не просто считай расходы. Найди путь наружу.'),const Spacer(),FilledButton(onPressed:()=>c.go('/onboarding'),child:const Text('Создать мой план')),TextButton(onPressed:()async{await r.read(authControllerProvider.notifier).demoLogin();if(c.mounted)c.go('/today');},child:const Text('Посмотреть демо'))]))));}
